import { fileURLToPath } from 'node:url';
import { migrate } from 'drizzle-orm/postgres-js/migrator';
import type { PostgresJsDatabase } from 'drizzle-orm/postgres-js';
import type { DbHandle } from './client';
import type * as schema from './schema';

/** SQL migrations generated by drizzle-kit (`pnpm --filter @gsc/db generate`). */
export const migrationsFolder = fileURLToPath(new URL('../migrations', import.meta.url));

/** Applies pending migrations. Uses the runtime migrator, so deploys don't need drizzle-kit. */
export async function migrateDb(handle: DbHandle): Promise<void> {
  await migrate(handle.db as unknown as PostgresJsDatabase<typeof schema>, { migrationsFolder });
}
